make_region <- function(prov_names, region_name) {
  sf_obj <- provinces %>%
    filter(shapeName %in% prov_names) %>%
    st_make_valid() %>%
    st_transform(32647)
  owin_obj <- as.owin(sf_obj %>% st_union() %>% st_zm(drop = TRUE, what = "ZM"))
  cat(region_name, ":", nrow(sf_obj), "provinces\n")
  list(sf = sf_obj, owin = owin_obj)
}

